#!/usr/bin/env node
// SS-018 D2: generates the SDK's contract files from the platform OpenAPI contract (the committed
// snapshot of https://api.storeshot.art/v1/openapi.json; located by scripts/inputs.mjs):
// src/generated/schema.ts (openapi-typescript, the generator and options the
// console uses) and src/generated/operations.ts (method, path and request traits per operationId).
// `--check` generates twice in memory and fails when the runs differ (non-deterministic) or differ
// from the committed files (stale). Never edit the generated files by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import { inputPath } from './inputs.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SPEC = inputPath('contract');
const OUT = resolve(root, 'src/generated');
const HEADER =
  '// Generated by scripts/generate.mjs (`npm run generate`) from the platform OpenAPI contract. Do not edit.\n' +
  '/* eslint-disable */\n';
const METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];

const sortKeys = (value) =>
  Array.isArray(value)
    ? value.map(sortKeys)
    : value && typeof value === 'object'
      ? Object.fromEntries(
          Object.keys(value)
            .sort()
            .map((key) => [key, sortKeys(value[key])]),
        )
      : value;

/** One entry per operationId: what the request core needs to build and retry the request. */
export function describeOperations(spec) {
  const operations = {};
  for (const [path, item] of Object.entries(spec.paths)) {
    for (const method of METHODS) {
      const op = item[method];
      if (!op?.operationId) continue;
      if (operations[op.operationId]) throw new Error(`duplicate operationId ${op.operationId}`);
      const params = [...(item.parameters ?? []), ...(op.parameters ?? [])];
      const named = (where) => params.filter((p) => p.in === where).map((p) => p.name);
      const contentTypes = Object.keys(op.requestBody?.content ?? {});
      const body =
        contentTypes.length === 0
          ? 'none'
          : contentTypes
              .map((type) =>
                type === 'application/json'
                  ? 'json'
                  : type === 'multipart/form-data'
                    ? 'multipart'
                    : type,
              )
              .sort()
              .join('|');
      const success = Object.keys(op.responses ?? {})
        .filter((status) => /^2\d\d$/.test(status))
        .map(Number)
        .sort((a, b) => a - b);
      const binary = success.some((status) =>
        Object.keys(op.responses[String(status)].content ?? {}).some(
          (type) => type !== 'application/json',
        ),
      );
      operations[op.operationId] = {
        method: method.toUpperCase(),
        path,
        tag: op.tags?.[0] ?? null,
        idempotencyKey: named('header').includes('idempotency-key'),
        wait: named('query').includes('wait'),
        pathParams: named('path'),
        queryParams: named('query').sort(),
        body,
        successStatuses: success,
        binary,
      };
    }
  }
  return sortKeys(operations);
}

export function operationsSource(spec) {
  const operations = describeOperations(spec);
  const errorCodes = spec.components.schemas.ErrorCode.enum;
  const events = Object.keys(spec.webhooks ?? {}).sort();
  return (
    HEADER +
    '\n/** `info.version` of the platform contract these files were generated from. */\n' +
    `export const CONTRACT_VERSION = ${JSON.stringify(spec.info.version)} as const;\n\n` +
    '/** Every `ErrorCode` of the contract (`ErrorEnvelope.error.code`). */\n' +
    `export const ERROR_CODES = ${JSON.stringify(errorCodes, null, 2)} as const;\n\n` +
    '/** Every webhook event type of the contract. */\n' +
    `export const WEBHOOK_EVENT_TYPES = ${JSON.stringify(events, null, 2)} as const;\n\n` +
    '/** Method, path and request traits of every operation, by operationId. */\n' +
    `export const OPERATIONS = ${JSON.stringify(operations, null, 2)} as const;\n\n` +
    'export type OperationId = keyof typeof OPERATIONS;\n' +
    'export type ErrorCode = (typeof ERROR_CODES)[number];\n' +
    'export type WebhookEventType = (typeof WEBHOOK_EVENT_TYPES)[number];\n'
  );
}

export async function generate(spec) {
  // openapi-typescript resolves $refs itself; hand it a copy so it can never mutate ours.
  // `defaultNonNullable: false` (the console keeps the default `true`): a request field with a
  // `default` (e.g. `app.description`) must stay optional for SDK callers.
  const ast = await openapiTS(structuredClone(spec), {
    alphabetize: true,
    defaultNonNullable: false,
  });
  return { schema: HEADER + astToString(ast), operations: operationsSource(spec) };
}

async function main() {
  const spec = JSON.parse(readFileSync(SPEC, 'utf8'));
  const first = await generate(spec);
  const files = { 'schema.ts': first.schema, 'operations.ts': first.operations };
  if (process.argv.includes('--check')) {
    const second = await generate(spec);
    if (second.schema !== first.schema || second.operations !== first.operations) {
      console.error('src/generated is non-deterministic: two runs differ.');
      process.exit(1);
    }
    for (const [name, text] of Object.entries(files)) {
      let current = '';
      try {
        current = readFileSync(resolve(OUT, name), 'utf8');
      } catch {
        current = '';
      }
      if (current !== text) {
        console.error(
          `src/generated/${name} is stale: run \`npm run generate\` in the SDK package.`,
        );
        process.exit(1);
      }
    }
    console.log(`src/generated matches the contract (${spec.info.version})`);
    return;
  }
  for (const [name, text] of Object.entries(files)) writeFileSync(resolve(OUT, name), text);
  console.log(`wrote src/generated/{schema,operations}.ts (contract ${spec.info.version})`);
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) await main();
